GRANT SELECT (id, account_type, display_name, avatar_path, cover_path, created_at, updated_at, verification_status, is_owner, is_hidden) ON public.profiles TO authenticated;
GRANT SELECT (id, current_club_name, level_id, primary_position, secondary_positions, preferred_level_id, availability, open_to_trials, height_inches, football_section, created_at, updated_at) ON public.players TO authenticated;
GRANT SELECT (id, name, short_name, badge_path, location, home_ground, league, level_id, founded, description, training_days, training_location, training_time, match_day, recruitment_status, created_at, updated_at, team_photo_path, home_ground_photo_path, training_pitch_photo_path, fees_policy, match_subs_fee, monthly_fee, yearly_fee, other_fee, other_fee_label, facilities, facilities_other, is_founder_club, founder_granted_at, football_section, active_section) ON public.clubs TO authenticated;